                      4 => ( CI_ipd'LAST_EVENT,
                             tpd_CI_S_posedge,
                             To_X01(CI_ipd) /= '1'),
                      5 => ( CI_ipd'LAST_EVENT,
                             tpd_CI_S_negedge,
                             To_X01(CI_ipd) /= '0')),
               GlitchData => S_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


