             trecovery_RN_CK_posedge_posedge : VitalDelayType := 0.0562499 ns;
             tremoval_RN_CK_posedge_posedge : VitalDelayType := -0.0124998 ns;
             tpw_CK_posedge : VitalDelayType := 0.125366 ns;
             tpw_CK_negedge : VitalDelayType := 0.0838481 ns;
             tpw_RN_negedge : VitalDelayType := 0.147237 ns;
             tpw_SN_negedge : VitalDelayType := 0.111884 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0625002 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0375 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0125001 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0124999 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.105499 ns, 0.116778 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.125366 ns, 0.113957 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.134851 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.143521 ns, 0 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.10233 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.124001 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.111215 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.132652 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
