                             To_X01(RN_dly) /= '1'),
                      2 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q_negedge,
                             To_X01(SN_dly) /= '1'),
                      3 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q_posedge,
                             To_X01(SN_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0'),
                      1 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN_negedge,
                             To_X01(RN_dly) /= '1'),
                      2 => ( SN_dly'LAST_EVENT,
                             tpd_SN_QN_negedge,
                             To_X01(SN_dly) /= '1'),
                      3 => ( SN_dly'LAST_EVENT,
                             tpd_SN_QN_posedge,
                             To_X01(SN_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
