             tpw_CK_posedge : VitalDelayType := 0.143074 ns;
             tpw_CK_negedge : VitalDelayType := 0.0851124 ns;
             tpw_RN_negedge : VitalDelayType := 0.163521 ns;
             tpw_SN_negedge : VitalDelayType := 0.125978 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0562499 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0375002 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0124997 ns;
