             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.140068 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.125142 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.149785 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
