             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.0187502 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.0249999 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := 0.00625024 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0437499 ns;
