             tpd_CK_Q_posedge : VitalDelayType01 := (0.0833574 ns, 0.0930996 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.108076 ns, 0.100266 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
