             tipd_C : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y : VitalDelayType01 := (0.114224 ns, 0.110182 ns);
             tpd_B_Y : VitalDelayType01 := (0.115102 ns, 0.110499 ns);
             tpd_C_Y : VitalDelayType01 := (0.112475 ns, 0.109021 ns);
             tpd_D_Y : VitalDelayType01 := (0.113369 ns, 0.109253 ns);
             tpd_S0_Y_posedge : VitalDelayType01 := (0.126737 ns, 0.104899 ns);
             tpd_S0_Y_negedge : VitalDelayType01 := (0.108412 ns, 0.125149 ns);
             tpd_S1_Y_posedge : VitalDelayType01 := (0.0794292 ns, 0.0881741 ns);
             tpd_S1_Y_negedge : VitalDelayType01 := (0.0912652 ns, 0.0779921 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
         B : in std_ulogic := 'U' ;
         C : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         S0 : in std_ulogic := 'U' ;
