             tipd_SN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SN_CKN : VitalDelayType := DefDummyIsd;
             trecovery_SN_CKN_posedge_negedge : VitalDelayType := 0.0249999 ns;
             tremoval_SN_CKN_posedge_negedge : VitalDelayType := 0.00625002 ns;
             trecovery_RN_SN_posedge_posedge : VitalDelayType := 0.0500001 ns;
             trecovery_RN_CKN_posedge_negedge : VitalDelayType := 0.0249999 ns;
             tremoval_RN_CKN_posedge_negedge : VitalDelayType := 0.0000000000541787 ns;
             tpw_CKN_posedge : VitalDelayType := 0.0739035 ns;
             tpw_CKN_negedge : VitalDelayType := 0.133333 ns;
             tpw_RN_negedge : VitalDelayType := 0.162131 ns;
             tpw_SN_negedge : VitalDelayType := 0.126358 ns;
             tsetup_SI_CKN_posedge_negedge : VitalDelayType := 0.0625001 ns;
             tsetup_SI_CKN_negedge_negedge : VitalDelayType := 0.0750002 ns;
             thold_SI_CKN_posedge_negedge : VitalDelayType := -0.0124999 ns;
             thold_SI_CKN_negedge_negedge : VitalDelayType := -0.0375001 ns;
             tsetup_SE_CKN_posedge_negedge : VitalDelayType := 0.08125 ns;
             tsetup_SE_CKN_negedge_negedge : VitalDelayType := 0.075 ns;
             thold_SE_CKN_posedge_negedge : VitalDelayType := -0.00625009 ns;
             thold_SE_CKN_negedge_negedge : VitalDelayType := -0.01875 ns;
             tsetup_D_CKN_posedge_negedge : VitalDelayType := 0.0625002 ns;
             tsetup_D_CKN_negedge_negedge : VitalDelayType := 0.075 ns;
             thold_D_CKN_posedge_negedge : VitalDelayType := -0.0125 ns;
             thold_D_CKN_negedge_negedge : VitalDelayType := -0.0374998 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CKN_Q_negedge : VitalDelayType01 := (0.138306 ns, 0.124189 ns);
             tpd_CKN_QN_negedge : VitalDelayType01 := (0.133332 ns, 0.139781 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.151228 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.160438 ns, 0 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.122212 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.139576 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.124095 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.148756 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CKN : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
