             tpd_CK_Q_posedge : VitalDelayType01 := (0.103081 ns, 0.0946606 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.109672 ns, 0.118787 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.0456464 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.0606272 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         RN : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
         Q : out std_ulogic ;
         QN : out std_ulogic);

   attribute VITAL_LEVEL0 of SDFFRX2 : entity is TRUE;
end SDFFRX2;

