architecture behavioral of SEDFFTRX4 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D_dly : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL E_dly : std_ulogic := 'X';
   SIGNAL E_ipd : std_ulogic := 'X';
   SIGNAL RN_dly : std_ulogic := 'X';
   SIGNAL RN_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';
   SIGNAL SI_dly : std_ulogic := 'X';
   SIGNAL SI_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( E_ipd, E, tipd_E );
   VitalWireDelay( RN_ipd, RN, tipd_RN );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
   VitalWireDelay( SI_ipd, SI, tipd_SI );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D_dly, D_ipd, tisd_D_CK );
   VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
   VitalSignalDelay( RN_dly, RN_ipd, tisd_RN_CK );
   VitalSignalDelay( SE_dly, SE_ipd, tisd_SE_CK );
   VitalSignalDelay( SI_dly, SI_ipd, tisd_SI_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D_dly, E_dly, RN_dly, SE_dly, SI_dly)

      --timing checks section variables
      VARIABLE Tviol_SI_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SI_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_SE_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_RN_CK : std_ulogic := '0';
      VARIABLE TimeMarker_RN_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_E_CK : std_ulogic := '0';
      VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE n7_var : std_ulogic;
      VARIABLE n8_var : std_ulogic;
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE QBINT : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE QN_zd : std_ulogic;
      VARIABLE SE_EQ_1 : std_ulogic;
      VARIABLE n9_var : std_ulogic;
      VARIABLE n10_var : std_ulogic;
      VARIABLE n11_var : std_ulogic;
      VARIABLE n12_var : std_ulogic;
      VARIABLE n13_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n14_var : std_ulogic;
      VARIABLE n15_var : std_ulogic;
      VARIABLE n16_var : std_ulogic;
      VARIABLE n17_var : std_ulogic;
      VARIABLE n18_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE n19_var : std_ulogic;
      VARIABLE n20_var : std_ulogic;
      VARIABLE n21_var : std_ulogic;
      VARIABLE D_EQ_1_AN_E_EQ_1_AN_RN_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE SE_EQ_0 : std_ulogic;
      VARIABLE n22_var : std_ulogic;
      VARIABLE RN_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n23_var : std_ulogic;
      VARIABLE n24_var : std_ulogic;
      VARIABLE E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n25_var : std_ulogic;
      VARIABLE n26_var : std_ulogic;
      VARIABLE n27_var : std_ulogic;
      VARIABLE n28_var : std_ulogic;
      VARIABLE n29_var : std_ulogic;
      VARIABLE n30_var : std_ulogic;
      VARIABLE n31_var : std_ulogic;
      VARIABLE n32_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;
      VARIABLE QN_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => SI_dly,
                    TestSignalName => "SI",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SI_CK_posedge_posedge,
                    SetupLow       => tsetup_SI_CK_negedge_posedge,
                    HoldHigh       => thold_SI_CK_posedge_posedge,
                    HoldLow        => thold_SI_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    TimingData     => TimeMarker_SI_CK,
                    Violation      => Tviol_SI_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => SE_dly,
                    TestSignalName => "SE",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SE_CK_posedge_posedge,
                    SetupLow       => tsetup_SE_CK_negedge_posedge,
                    HoldHigh       => thold_SE_CK_posedge_posedge,
                    HoldLow        => thold_SE_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    TimingData     => TimeMarker_SE_CK,
                    Violation      => Tviol_SE_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => RN_dly,
                    TestSignalName => "RN",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_RN_CK_posedge_posedge,
                    SetupLow       => tsetup_RN_CK_negedge_posedge,
                    HoldHigh       => thold_RN_CK_posedge_posedge,
                    HoldLow        => thold_RN_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    TimingData     => TimeMarker_RN_CK,
                    Violation      => Tviol_RN_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => E_dly,
                    TestSignalName => "E",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_E_CK_posedge_posedge,
                    SetupLow       => tsetup_E_CK_negedge_posedge,
                    HoldHigh       => thold_E_CK_posedge_posedge,
                    HoldLow        => thold_E_CK_negedge_posedge,
                    CheckEnabled   => To_X01(RN_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    TimingData     => TimeMarker_E_CK,
                    Violation      => Tviol_E_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D_dly,
                    TestSignalName => "D",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D_CK_posedge_posedge,
                    SetupLow       => tsetup_D_CK_negedge_posedge,
                    HoldHigh       => thold_D_CK_posedge_posedge,
                    HoldLow        => thold_D_CK_negedge_posedge,
                    CheckEnabled   => To_X01(E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    TimingData     => TimeMarker_D_CK,
                    Violation      => Tviol_D_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/SEDFFTRX4",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_RN_CK OR
                        Tviol_E_CK OR
                        Tviol_D_CK OR
                        PWviol_CK );

          n1_var := VitalINV(D_dly);
          n2_var := VitalAND2(n1_var, E_dly);
          n3_var := VitalINV(n2_var);
          n4_var := VitalINV(E_dly);
          n5_var := VitalAND2(n4_var, QBINT);
          n6_var := VitalINV(n5_var);
          n7_var := VitalAND2(n3_var, n6_var);
          n8_var := VitalAND2(n7_var, RN_dly);
          n0_D := VitalMUX2(SI_dly, n8_var, SE_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          QN_zd := VitalBUF(QBINT);

          SE_EQ_1 := VitalBUF(SE_dly);

          n9_var := VitalINV(D_dly);
          n10_var := VitalINV(E_dly);
          n11_var := VitalAND2(n9_var, n10_var);
          n12_var := VitalINV(RN_dly);
          n13_var := VitalAND2(n11_var, n12_var);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1 := VitalAND2(n13_var, SI_dly);

          n14_var := VitalINV(D_dly);
          n15_var := VitalINV(E_dly);
          n16_var := VitalAND2(n14_var, n15_var);
          n17_var := VitalAND2(n16_var, RN_dly);
          n18_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n17_var, n18_var);

          n19_var := VitalAND2(D_dly, E_dly);
          n20_var := VitalAND2(n19_var, RN_dly);
          n21_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n20_var, n21_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n22_var := VitalINV(SE_dly);
          RN_EQ_1_AN_SE_EQ_0 := VitalAND2(RN_dly, n22_var);

          n23_var := VitalAND2(E_dly, RN_dly);
          n24_var := VitalINV(SE_dly);
          E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0 := VitalAND2(n23_var, n24_var);

          n25_var := VitalINV(D_dly);
          n26_var := VitalINV(E_dly);
          n27_var := VitalAND2(n25_var, n26_var);
          n28_var := VitalINV(RN_dly);
          n29_var := VitalAND2(n27_var, n28_var);
          n30_var := VitalINV(SE_dly);
          n31_var := VitalAND2(n29_var, n30_var);
          n32_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 := VitalAND2(n31_var, n32_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity SEDFFTRXL is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_E : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_E_CK : VitalDelayType := DefDummyIsd;
             tipd_RN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_RN_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tipd_SI : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SI_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.14144 ns;
             tpw_CK_negedge : VitalDelayType := 0.059255 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0562502 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.0437501 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0374997 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.01875 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0562499 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.06875 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0249999 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0124998 ns;
             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.13125 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.0812503 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.0499997 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.125 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0875 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0624999 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0624999 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.1125 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0812498 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0812498 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0562501 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.126958 ns, 0.133812 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.141786 ns, 0.127933 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         RN : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
         Q : out std_ulogic ;
         QN : out std_ulogic);

   attribute VITAL_LEVEL0 of SEDFFTRXL : entity is TRUE;
end SEDFFTRXL;

architecture behavioral of SEDFFTRXL is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D_dly : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL E_dly : std_ulogic := 'X';
   SIGNAL E_ipd : std_ulogic := 'X';
   SIGNAL RN_dly : std_ulogic := 'X';
   SIGNAL RN_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';
   SIGNAL SI_dly : std_ulogic := 'X';
   SIGNAL SI_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( E_ipd, E, tipd_E );
   VitalWireDelay( RN_ipd, RN, tipd_RN );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
   VitalWireDelay( SI_ipd, SI, tipd_SI );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D_dly, D_ipd, tisd_D_CK );
   VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
   VitalSignalDelay( RN_dly, RN_ipd, tisd_RN_CK );
   VitalSignalDelay( SE_dly, SE_ipd, tisd_SE_CK );
   VitalSignalDelay( SI_dly, SI_ipd, tisd_SI_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D_dly, E_dly, RN_dly, SE_dly, SI_dly)

      --timing checks section variables
      VARIABLE Tviol_SI_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SI_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_SE_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_RN_CK : std_ulogic := '0';
      VARIABLE TimeMarker_RN_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_E_CK : std_ulogic := '0';
      VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE n7_var : std_ulogic;
      VARIABLE n8_var : std_ulogic;
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE QBINT : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE QN_zd : std_ulogic;
      VARIABLE SE_EQ_1 : std_ulogic;
      VARIABLE n9_var : std_ulogic;
      VARIABLE n10_var : std_ulogic;
      VARIABLE n11_var : std_ulogic;
      VARIABLE n12_var : std_ulogic;
      VARIABLE n13_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n14_var : std_ulogic;
      VARIABLE n15_var : std_ulogic;
      VARIABLE n16_var : std_ulogic;
      VARIABLE n17_var : std_ulogic;
      VARIABLE n18_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE n19_var : std_ulogic;
      VARIABLE n20_var : std_ulogic;
      VARIABLE n21_var : std_ulogic;
      VARIABLE D_EQ_1_AN_E_EQ_1_AN_RN_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE SE_EQ_0 : std_ulogic;
      VARIABLE n22_var : std_ulogic;
      VARIABLE RN_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n23_var : std_ulogic;
      VARIABLE n24_var : std_ulogic;
      VARIABLE E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n25_var : std_ulogic;
      VARIABLE n26_var : std_ulogic;
      VARIABLE n27_var : std_ulogic;
      VARIABLE n28_var : std_ulogic;
      VARIABLE n29_var : std_ulogic;
      VARIABLE n30_var : std_ulogic;
      VARIABLE n31_var : std_ulogic;
      VARIABLE n32_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;
      VARIABLE QN_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => SI_dly,
                    TestSignalName => "SI",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SI_CK_posedge_posedge,
                    SetupLow       => tsetup_SI_CK_negedge_posedge,
                    HoldHigh       => thold_SI_CK_posedge_posedge,
                    HoldLow        => thold_SI_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    TimingData     => TimeMarker_SI_CK,
                    Violation      => Tviol_SI_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => SE_dly,
                    TestSignalName => "SE",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SE_CK_posedge_posedge,
                    SetupLow       => tsetup_SE_CK_negedge_posedge,
                    HoldHigh       => thold_SE_CK_posedge_posedge,
                    HoldLow        => thold_SE_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    TimingData     => TimeMarker_SE_CK,
                    Violation      => Tviol_SE_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => RN_dly,
                    TestSignalName => "RN",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_RN_CK_posedge_posedge,
                    SetupLow       => tsetup_RN_CK_negedge_posedge,
                    HoldHigh       => thold_RN_CK_posedge_posedge,
                    HoldLow        => thold_RN_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    TimingData     => TimeMarker_RN_CK,
                    Violation      => Tviol_RN_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => E_dly,
                    TestSignalName => "E",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_E_CK_posedge_posedge,
                    SetupLow       => tsetup_E_CK_negedge_posedge,
                    HoldHigh       => thold_E_CK_posedge_posedge,
                    HoldLow        => thold_E_CK_negedge_posedge,
                    CheckEnabled   => To_X01(RN_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    TimingData     => TimeMarker_E_CK,
                    Violation      => Tviol_E_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D_dly,
                    TestSignalName => "D",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D_CK_posedge_posedge,
                    SetupLow       => tsetup_D_CK_negedge_posedge,
                    HoldHigh       => thold_D_CK_posedge_posedge,
                    HoldLow        => thold_D_CK_negedge_posedge,
                    CheckEnabled   => To_X01(E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    TimingData     => TimeMarker_D_CK,
                    Violation      => Tviol_D_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/SEDFFTRXL",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_RN_CK OR
                        Tviol_E_CK OR
                        Tviol_D_CK OR
                        PWviol_CK );

          n1_var := VitalINV(D_dly);
          n2_var := VitalAND2(n1_var, E_dly);
          n3_var := VitalINV(n2_var);
          n4_var := VitalINV(E_dly);
          n5_var := VitalAND2(n4_var, QBINT);
          n6_var := VitalINV(n5_var);
          n7_var := VitalAND2(n3_var, n6_var);
          n8_var := VitalAND2(n7_var, RN_dly);
          n0_D := VitalMUX2(SI_dly, n8_var, SE_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          QBINT := VitalINV(N30);

          Q_zd := VitalINV(QBINT);

          QN_zd := VitalBUF(QBINT);

          SE_EQ_1 := VitalBUF(SE_dly);

          n9_var := VitalINV(D_dly);
          n10_var := VitalINV(E_dly);
          n11_var := VitalAND2(n9_var, n10_var);
          n12_var := VitalINV(RN_dly);
          n13_var := VitalAND2(n11_var, n12_var);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SI_EQ_1 := VitalAND2(n13_var, SI_dly);

          n14_var := VitalINV(D_dly);
          n15_var := VitalINV(E_dly);
          n16_var := VitalAND2(n14_var, n15_var);
          n17_var := VitalAND2(n16_var, RN_dly);
          n18_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n17_var, n18_var);

          n19_var := VitalAND2(D_dly, E_dly);
          n20_var := VitalAND2(n19_var, RN_dly);
          n21_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_RN_EQ_1_AN_SI_EQ_0 := VitalAND2(n20_var, n21_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n22_var := VitalINV(SE_dly);
          RN_EQ_1_AN_SE_EQ_0 := VitalAND2(RN_dly, n22_var);

          n23_var := VitalAND2(E_dly, RN_dly);
          n24_var := VitalINV(SE_dly);
          E_EQ_1_AN_RN_EQ_1_AN_SE_EQ_0 := VitalAND2(n23_var, n24_var);

          n25_var := VitalINV(D_dly);
          n26_var := VitalINV(E_dly);
          n27_var := VitalAND2(n25_var, n26_var);
          n28_var := VitalINV(RN_dly);
          n29_var := VitalAND2(n27_var, n28_var);
          n30_var := VitalINV(SE_dly);
          n31_var := VitalAND2(n29_var, n30_var);
          n32_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_RN_EQ_0_AN_SE_EQ_0_AN_SI_EQ_0 := VitalAND2(n31_var, n32_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity SEDFFX2 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_E : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_E_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tipd_SI : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SI_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.118745 ns;
             tpw_CK_negedge : VitalDelayType := 0.06328 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.05625 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.04375 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0312501 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0125001 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0562501 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0687501 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0250002 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.0875001 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0812501 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0624999 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.03125 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0937502 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0812502 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0624999 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0375 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.0842307 ns, 0.0934847 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.118628 ns, 0.111709 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         SI : in std_ulogic := 'U' ;
         Q : out std_ulogic ;
         QN : out std_ulogic);

   attribute VITAL_LEVEL0 of SEDFFX2 : entity is TRUE;
end SEDFFX2;

architecture behavioral of SEDFFX2 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL D_dly : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL E_dly : std_ulogic := 'X';
   SIGNAL E_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';
   SIGNAL SI_dly : std_ulogic := 'X';
   SIGNAL SI_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( E_ipd, E, tipd_E );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
   VitalWireDelay( SI_ipd, SI, tipd_SI );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D_dly, D_ipd, tisd_D_CK );
   VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
   VitalSignalDelay( SE_dly, SE_ipd, tisd_SE_CK );
   VitalSignalDelay( SI_dly, SI_ipd, tisd_SI_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D_dly, E_dly, SE_dly, SI_dly)

      --timing checks section variables
      VARIABLE Tviol_SI_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SI_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_SE_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_E_CK : std_ulogic := '0';
      VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE NET536 : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE QN_zd : std_ulogic;
      VARIABLE SE_EQ_1 : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0 : std_ulogic;
      VARIABLE n7_var : std_ulogic;
      VARIABLE n8_var : std_ulogic;
      VARIABLE n9_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n10_var : std_ulogic;
      VARIABLE n11_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_1_AN_SI_EQ_1 : std_ulogic;
      VARIABLE n12_var : std_ulogic;
      VARIABLE n13_var : std_ulogic;
      VARIABLE D_EQ_1_AN_E_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE SE_EQ_0 : std_ulogic;
      VARIABLE n14_var : std_ulogic;
      VARIABLE E_EQ_1_AN_SE_EQ_0 : std_ulogic;
      VARIABLE n15_var : std_ulogic;
      VARIABLE n16_var : std_ulogic;
      VARIABLE n17_var : std_ulogic;
      VARIABLE n18_var : std_ulogic;
      VARIABLE n19_var : std_ulogic;
      VARIABLE D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;
      VARIABLE QN_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => SI_dly,
                    TestSignalName => "SI",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SI_CK_posedge_posedge,
                    SetupLow       => tsetup_SI_CK_negedge_posedge,
                    HoldHigh       => thold_SI_CK_posedge_posedge,
                    HoldLow        => thold_SI_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFX2",
                    TimingData     => TimeMarker_SI_CK,
                    Violation      => Tviol_SI_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => SE_dly,
                    TestSignalName => "SE",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SE_CK_posedge_posedge,
                    SetupLow       => tsetup_SE_CK_negedge_posedge,
                    HoldHigh       => thold_SE_CK_posedge_posedge,
                    HoldLow        => thold_SE_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFX2",
                    TimingData     => TimeMarker_SE_CK,
                    Violation      => Tviol_SE_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => E_dly,
                    TestSignalName => "E",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_E_CK_posedge_posedge,
                    SetupLow       => tsetup_E_CK_negedge_posedge,
                    HoldHigh       => thold_E_CK_posedge_posedge,
                    HoldLow        => thold_E_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFX2",
                    TimingData     => TimeMarker_E_CK,
                    Violation      => Tviol_E_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D_dly,
                    TestSignalName => "D",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D_CK_posedge_posedge,
                    SetupLow       => tsetup_D_CK_negedge_posedge,
                    HoldHigh       => thold_D_CK_posedge_posedge,
                    HoldLow        => thold_D_CK_negedge_posedge,
                    CheckEnabled   => To_X01(E_EQ_1_AN_SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/SEDFFX2",
                    TimingData     => TimeMarker_D_CK,
                    Violation      => Tviol_D_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/SEDFFX2",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_E_CK OR
                        Tviol_D_CK OR
                        PWviol_CK );

          n1_var := VitalINV(NET536);
          n2_var := VitalMUX2(D_dly, n1_var, E_dly);
          n0_D := VitalMUX2(SI_dly, n2_var, SE_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_dff_n0 );

          N30 := n0_vec(1);

          NET536 := VitalINV(N30);

          Q_zd := VitalINV(NET536);

          QN_zd := VitalBUF(NET536);

          SE_EQ_1 := VitalBUF(SE_dly);

          n3_var := VitalINV(D_dly);
          n4_var := VitalINV(E_dly);
          n5_var := VitalAND2(n3_var, n4_var);
          n6_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_SI_EQ_0 := VitalAND2(n5_var, n6_var);

          n7_var := VitalINV(D_dly);
          n8_var := VitalINV(E_dly);
          n9_var := VitalAND2(n7_var, n8_var);
          D_EQ_0_AN_E_EQ_0_AN_SI_EQ_1 := VitalAND2(n9_var, SI_dly);

          n10_var := VitalINV(D_dly);
          n11_var := VitalAND2(n10_var, E_dly);
          D_EQ_0_AN_E_EQ_1_AN_SI_EQ_1 := VitalAND2(n11_var, SI_dly);

          n12_var := VitalAND2(D_dly, E_dly);
          n13_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_SI_EQ_0 := VitalAND2(n12_var, n13_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n14_var := VitalINV(SE_dly);
          E_EQ_1_AN_SE_EQ_0 := VitalAND2(E_dly, n14_var);

          n15_var := VitalINV(D_dly);
          n16_var := VitalINV(E_dly);
          n17_var := VitalAND2(n15_var, n16_var);
          n18_var := VitalAND2(n17_var, SE_dly);
          n19_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0 := VitalAND2(n18_var, n19_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_Q_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_QN_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


