             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0312499 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0312497 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0250001 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0250002 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.03125 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0312501 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0250003 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.025 ns;
             tpd_CK_ECK_negedge : VitalDelayType01 := (0 ns, 0.0686192 ns);
             tpd_CK_ECK_posedge : VitalDelayType01 := (0.0778728 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
