             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.0713622 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.0522101 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.0702463 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         D : in std_ulogic := 'U' ;
         G : in std_ulogic := 'U' ;
         RN : in std_ulogic := 'U' ;
         SN : in std_ulogic := 'U' ;
