             tpw_RN_negedge : VitalDelayType := 0.160295 ns;
             tpw_SN_negedge : VitalDelayType := 0.124476 ns;
             tsetup_D_CKN_posedge_negedge : VitalDelayType := 0.0312502 ns;
             tsetup_D_CKN_negedge_negedge : VitalDelayType := 0.0437499 ns;
             thold_D_CKN_posedge_negedge : VitalDelayType := 0.0125 ns;
             thold_D_CKN_negedge_negedge : VitalDelayType := -0.0124999 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CKN_Q_negedge : VitalDelayType01 := (0.135902 ns, 0.120313 ns);
             tpd_CKN_QN_negedge : VitalDelayType01 := (0.129867 ns, 0.13778 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.148726 ns);
