             thold_E_CK_posedge_posedge : VitalDelayType := -0.0375001 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := 0.00625012 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0562501 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0500002 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0374998 ns;
