             tpw_CK_negedge : VitalDelayType := 0.0632807 ns;
             tsetup_S0_CK_posedge_posedge : VitalDelayType := 0.0437499 ns;
             tsetup_S0_CK_negedge_posedge : VitalDelayType := 0.0562502 ns;
             thold_S0_CK_posedge_posedge : VitalDelayType := -0.0125001 ns;
             thold_S0_CK_negedge_posedge : VitalDelayType := -0.0000000000541919 ns;
