USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity MXI4X4 is
   generic (
             tipd_A : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_C : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_D : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_S1 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y : VitalDelayType01 := (0.0932554 ns, 0.0938338 ns);
             tpd_B_Y : VitalDelayType01 := (0.0938397 ns, 0.0937146 ns);
             tpd_C_Y : VitalDelayType01 := (0.091136 ns, 0.0926587 ns);
             tpd_D_Y : VitalDelayType01 := (0.0923033 ns, 0.0932925 ns);
             tpd_S0_Y_posedge : VitalDelayType01 := (0.10414 ns, 0.0888968 ns);
             tpd_S0_Y_negedge : VitalDelayType01 := (0.0873429 ns, 0.107397 ns);
             tpd_S1_Y_posedge : VitalDelayType01 := (0.0543604 ns, 0.0743945 ns);
             tpd_S1_Y_negedge : VitalDelayType01 := (0.072674 ns, 0.0575313 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
         B : in std_ulogic := 'U' ;
         C : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
         S0 : in std_ulogic := 'U' ;
         S1 : in std_ulogic := 'U' ;
         Y : out std_ulogic);

   attribute VITAL_LEVEL0 of MXI4X4 : entity is TRUE;
end MXI4X4;

architecture behavioral of MXI4X4 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL A_ipd : std_ulogic := 'X';
   SIGNAL B_ipd : std_ulogic := 'X';
   SIGNAL C_ipd : std_ulogic := 'X';
   SIGNAL D_ipd : std_ulogic := 'X';
   SIGNAL S0_ipd : std_ulogic := 'X';
   SIGNAL S1_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( A_ipd, A, tipd_A );
   VitalWireDelay( B_ipd, B, tipd_B );
   VitalWireDelay( C_ipd, C, tipd_C );
   VitalWireDelay( D_ipd, D, tipd_D );
   VitalWireDelay( S0_ipd, S0, tipd_S0 );
   VitalWireDelay( S1_ipd, S1, tipd_S1 );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd, C_ipd, D_ipd, S0_ipd, S1_ipd)


      -- functionality section variables
      VARIABLE n0_var : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE Y_zd : std_ulogic;

      -- path delay section variables
      VARIABLE Y_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          n0_var := VitalMUX2(D_ipd, C_ipd, S0_ipd);
          n1_var := VitalMUX2(B_ipd, A_ipd, S0_ipd);
          n2_var := VitalMUX2(n0_var, n1_var, S1_ipd);
          Y_zd := VitalINV(n2_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y,
                             TRUE),
                      1 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y,
                             TRUE),
                      2 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y,
                             TRUE),
                      3 => ( D_ipd'LAST_EVENT,
                             tpd_D_Y,
                             TRUE),
                      4 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_posedge,
                             To_X01(S0_ipd) /= '1'),
                      5 => ( S0_ipd'LAST_EVENT,
                             tpd_S0_Y_negedge,
                             To_X01(S0_ipd) /= '0'),
                      6 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_posedge,
                             To_X01(S1_ipd) /= '1'),
                      7 => ( S1_ipd'LAST_EVENT,
                             tpd_S1_Y_negedge,
                             To_X01(S1_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


