             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0624999 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.0437498 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.03125 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0562496 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.06875 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0125002 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.00624992 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0625002 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0437502 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0312501 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.0985227 ns, 0.0900052 ns);
