             thold_D_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.0985475 ns, 0.10598 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.120792 ns, 0.115168 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.131434 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.146234 ns, 0 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.0913438 ns, 0 ns);
