   VitalSignalDelay( GN_dly, GN_ipd, tisd_GN_RN );
   VitalSignalDelay( RN_dly, RN_ipd, ticd_RN );
   VitalSignalDelay( SN_dly, SN_ipd, tisd_SN_RN );
END BLOCK;

VITALBehavior : PROCESS (D_dly, GN_dly, RN_dly, SN_dly)

      --timing checks section variables
      VARIABLE Tviol_rec_RN_SN_posedge : std_ulogic := '0';
      VARIABLE TimeMarker_rec_RN_SN_posedge : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_rec_GN_SN_posedge : std_ulogic := '0';
      VARIABLE TimeMarker_rec_GN_SN_posedge : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_RN_GN : std_ulogic := '0';
      VARIABLE TimeMarker_RN_GN : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D_GN : std_ulogic := '0';
      VARIABLE TimeMarker_D_GN : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_SN_negedge : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_SN_negedge : VitalPeriodDataType;
      VARIABLE PWviol_RN_negedge : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_RN_negedge : VitalPeriodDataType;
      VARIABLE PWviol_GN_negedge : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_GN_negedge : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n1_var : std_ulogic;
      VARIABLE n0_ENABLE : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SET : std_ulogic;
      VARIABLE QINT : std_ulogic;
      VARIABLE N5 : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_tlat_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE QN_zd : std_ulogic;
      VARIABLE GN_EQ_1 : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE D_EQ_0_AN_RN_EQ_1 : std_ulogic;
      VARIABLE D_EQ_1_AN_SN_EQ_1 : std_ulogic;
      VARIABLE RN_EQ_1_AN_SN_EQ_1 : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE D_EQ_0_AN_SN_EQ_1 : std_ulogic;
      VARIABLE D_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;
      VARIABLE QN_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalRecoveryRemovalCheck (
                    TestSignal     => SN_dly,
                    TestSignalName => "SN",
                    RefSignal      => RN_dly,
                    RefSignalName  => "RN",
                    Recovery       => trecovery_SN_RN_posedge_posedge,
                    Removal        => tremoval_SN_RN_posedge_posedge,
                    CheckEnabled   => To_X01(GN_EQ_1) /= '0',
                    ActiveLow      => TRUE,
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    TimingData     => TimeMarker_rec_RN_SN_posedge,
                    Violation      => Tviol_rec_RN_SN_posedge,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalRecoveryRemovalCheck (
                    TestSignal     => SN_dly,
                    TestSignalName => "SN",
                    RefSignal      => GN_dly,
                    RefSignalName  => "GN",
                    Recovery       => trecovery_SN_GN_posedge_posedge,
                    Removal        => tremoval_SN_GN_posedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_0_AN_RN_EQ_1) /= '0',
                    ActiveLow      => TRUE,
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    TimingData     => TimeMarker_rec_GN_SN_posedge,
                    Violation      => Tviol_rec_GN_SN_posedge,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => RN_dly,
                    TestSignalName => "RN",
                    RefSignal      => GN_dly,
                    RefSignalName  => "GN",
                    SetupHigh      => tsetup_RN_GN_posedge_posedge,
                    SetupLow       => 0 ns,
                    HoldHigh       => 0 ns,
                    HoldLow        => thold_RN_GN_negedge_posedge,
                    CheckEnabled   => To_X01(D_EQ_1_AN_SN_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    TimingData     => TimeMarker_RN_GN,
                    Violation      => Tviol_RN_GN,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D_dly,
                    TestSignalName => "D",
                    RefSignal      => GN_dly,
                    RefSignalName  => "GN",
                    SetupHigh      => tsetup_D_GN_posedge_posedge,
                    SetupLow       => tsetup_D_GN_negedge_posedge,
                    HoldHigh       => thold_D_GN_posedge_posedge,
                    HoldLow        => thold_D_GN_negedge_posedge,
                    CheckEnabled   => To_X01(RN_EQ_1_AN_SN_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    TimingData     => TimeMarker_D_GN,
                    Violation      => Tviol_D_GN,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => SN_dly,
                    TestSignalName => "SN",
                    Period         => 0 ps,
                    PulseWidthHigh => 0 ns,
                    PulseWidthLow  => tpw_SN_negedge,
                    PeriodData     => PeriodCheckInfo_SN_negedge,
                    Violation      => PWviol_SN_negedge,
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    CheckEnabled   => To_X01(D_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => RN_dly,
                    TestSignalName => "RN",
                    Period         => 0 ps,
                    PulseWidthHigh => 0 ns,
                    PulseWidthLow  => tpw_RN_negedge,
                    PeriodData     => PeriodCheckInfo_RN_negedge,
                    Violation      => PWviol_RN_negedge,
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    CheckEnabled   => To_X01(D_EQ_0_AN_SN_EQ_1) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => GN_dly,
                    TestSignalName => "GN",
                    Period         => 0 ps,
                    PulseWidthHigh => 0 ns,
                    PulseWidthLow  => tpw_GN_negedge,
                    PeriodData     => PeriodCheckInfo_GN_negedge,
                    Violation      => PWviol_GN_negedge,
                    HeaderMsg      => InstancePath & "/TLATNSRX2",
                    CheckEnabled   => To_X01(D_EQ_0_AN_SN_EQ_1) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_rec_RN_SN_posedge OR
                        Tviol_rec_GN_SN_posedge OR
                        Tviol_RN_GN OR
                        Tviol_D_GN OR
                        PWviol_SN_negedge OR
                        PWviol_RN_negedge OR
                        PWviol_GN_negedge );

          n1_var := VitalINV(GN_dly);
          n0_ENABLE := VitalAND2(n1_var, RN_dly);

          n0_RN_dly := '0';

          n0_SET := VitalINV(SN_dly);

          VitalStateTable ( StateTable => udp_tlat,
                                DataIn => (NOTIFIER, D_dly, n0_ENABLE, n0_RN_dly, n0_SET),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_tlat_n0 );

          QINT := n0_vec(1);

          N5 := VitalINV(QINT);

          Q_zd := VitalBUF(QINT);

          QN_zd := VitalINV(QINT);

          GN_EQ_1 := VitalBUF(GN_dly);

          n2_var := VitalINV(D_dly);
          D_EQ_0_AN_RN_EQ_1 := VitalAND2(n2_var, RN_dly);

          D_EQ_1_AN_SN_EQ_1 := VitalAND2(D_dly, SN_dly);

          RN_EQ_1_AN_SN_EQ_1 := VitalAND2(RN_dly, SN_dly);

          n3_var := VitalINV(D_dly);
          D_EQ_0_AN_SN_EQ_1 := VitalAND2(n3_var, SN_dly);

          D_EQ_0 := VitalINV(D_dly);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
               OutTemp => Q_zd,
               Paths => (
                      0 => ( D_dly'LAST_EVENT,
                             tpd_D_Q,
                             TRUE),
                      1 => ( GN_dly'LAST_EVENT,
                             tpd_GN_Q_negedge,
                             To_X01(GN_dly) /= '1'),
                      2 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q_negedge,
                             To_X01(RN_dly) /= '1'),
                      3 => ( RN_dly'LAST_EVENT,
                             tpd_RN_Q_posedge,
                             To_X01(RN_dly) /= '0'),
                      4 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q_negedge,
                             To_X01(SN_dly) /= '1'),
                      5 => ( SN_dly'LAST_EVENT,
                             tpd_SN_Q_posedge,
                             To_X01(SN_dly) /= '0')),
               GlitchData => Q_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );

          VitalPathDelay01(
               OutSignal     => QN,
               OutSignalName => "QN",
               OutTemp => QN_zd,
               Paths => (
                      0 => ( D_dly'LAST_EVENT,
                             tpd_D_QN,
                             TRUE),
                      1 => ( GN_dly'LAST_EVENT,
                             tpd_GN_QN_negedge,
                             To_X01(GN_dly) /= '1'),
                      2 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN_negedge,
                             To_X01(RN_dly) /= '1'),
                      3 => ( RN_dly'LAST_EVENT,
                             tpd_RN_QN_posedge,
                             To_X01(RN_dly) /= '0'),
                      4 => ( SN_dly'LAST_EVENT,
                             tpd_SN_QN_negedge,
                             To_X01(SN_dly) /= '1'),
                      5 => ( SN_dly'LAST_EVENT,
                             tpd_SN_QN_posedge,
                             To_X01(SN_dly) /= '0')),
               GlitchData => QN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


LIBRARY IEEE;
USE IEEE.Std_logic_1164.all;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;
USE work.prim.all;

entity TLATNTSCAX12 is
   generic (
             tipd_CK : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             ticd_CK : VitalDelayType := DefDummyIcd;
             tipd_E : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_E_CK : VitalDelayType := DefDummyIsd;
             tipd_SE : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SE_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_negedge : VitalDelayType := 0.082315 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0312501 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0312503 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0249998 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.025 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.03125 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0312501 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0250002 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0249998 ns;
             tpd_CK_ECK_negedge : VitalDelayType01 := (0 ns, 0.0738177 ns);
             tpd_CK_ECK_posedge : VitalDelayType01 := (0.0840958 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         ECK : out std_ulogic);

   attribute VITAL_LEVEL0 of TLATNTSCAX12 : entity is TRUE;
end TLATNTSCAX12;

architecture behavioral of TLATNTSCAX12 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL CK_dly : std_ulogic := 'X';
   SIGNAL CK_ipd : std_ulogic := 'X';
   SIGNAL E_dly : std_ulogic := 'X';
   SIGNAL E_ipd : std_ulogic := 'X';
   SIGNAL SE_dly : std_ulogic := 'X';
   SIGNAL SE_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( E_ipd, E, tipd_E );
   VitalWireDelay( SE_ipd, SE, tipd_SE );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( E_dly, E_ipd, tisd_E_CK );
   VitalSignalDelay( SE_dly, SE_ipd, tisd_SE_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, E_dly, SE_dly)

      --timing checks section variables
      VARIABLE Tviol_SE_CK : std_ulogic := '0';
      VARIABLE TimeMarker_SE_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_E_CK : std_ulogic := '0';
      VARIABLE TimeMarker_E_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK_negedge : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK_negedge : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n0_D : std_ulogic;
      VARIABLE n0_ENABLE : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE EINT : std_ulogic;
      VARIABLE N5 : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_tlat_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE ECK_zd : std_ulogic;
      VARIABLE E_EQ_0 : std_ulogic;
      VARIABLE SE_EQ_0 : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE E_EQ_0_AN_SE_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE ECK_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => SE_dly,
                    TestSignalName => "SE",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_SE_CK_posedge_posedge,
                    SetupLow       => tsetup_SE_CK_negedge_posedge,
                    HoldHigh       => thold_SE_CK_posedge_posedge,
                    HoldLow        => thold_SE_CK_negedge_posedge,
                    CheckEnabled   => To_X01(E_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNTSCAX12",
                    TimingData     => TimeMarker_SE_CK,
                    Violation      => Tviol_SE_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => E_dly,
                    TestSignalName => "E",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_E_CK_posedge_posedge,
                    SetupLow       => tsetup_E_CK_negedge_posedge,
                    HoldHigh       => thold_E_CK_posedge_posedge,
                    HoldLow        => thold_E_CK_negedge_posedge,
                    CheckEnabled   => To_X01(SE_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/TLATNTSCAX12",
                    TimingData     => TimeMarker_E_CK,
                    Violation      => Tviol_E_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => 0 ns,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK_negedge,
                    Violation      => PWviol_CK_negedge,
                    HeaderMsg      => InstancePath & "/TLATNTSCAX12",
                    CheckEnabled   => To_X01(E_EQ_0_AN_SE_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SE_CK OR
                        Tviol_E_CK OR
                        PWviol_CK_negedge );

          n0_D := VitalOR2(E_dly, SE_dly);

          n0_ENABLE := VitalINV(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_tlat,
                                DataIn => (NOTIFIER, n0_D, n0_ENABLE, n0_RN_dly, n0_SN_dly),
                             NumStates => 1,
                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_tlat_n0 );

          EINT := n0_vec(1);

          N5 := VitalINV(EINT);

          ECK_zd := VitalAND2(CK_dly, EINT);

          E_EQ_0 := VitalINV(E_dly);

          SE_EQ_0 := VitalINV(SE_dly);

          n1_var := VitalINV(E_dly);
          n2_var := VitalINV(SE_dly);
          E_EQ_0_AN_SE_EQ_0 := VitalAND2(n1_var, n2_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => ECK,
               OutSignalName => "ECK",
               OutTemp => ECK_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK_negedge,
                             To_X01(CK_dly) /= '1'),
                      1 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => ECK_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


