             tpd_A_Y : VitalDelayType01 := (0.0602765 ns, 0.0511341 ns);
             tpd_B_Y : VitalDelayType01 := (0.0588029 ns, 0.0499167 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
