             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.122185 ns;
             tpw_CK_negedge : VitalDelayType := 0.0730138 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0250002 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0125001 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0124997 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0125001 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.115641 ns, 0.122185 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
