                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/EDFFHQX8",
                    CheckEnabled   => To_X01(D_EQ_0_AN_E_EQ_1) /= '0',
                    XOn            => DefSeqXOn,
