             thold_SE_CKN_negedge_negedge : VitalDelayType := -0.0125001 ns;
             tsetup_D_CKN_posedge_negedge : VitalDelayType := 0.06875 ns;
             tsetup_D_CKN_negedge_negedge : VitalDelayType := 0.0875 ns;
             thold_D_CKN_posedge_negedge : VitalDelayType := -0.00624998 ns;
