             tpw_CK_negedge : VitalDelayType := 0.0591281 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0562498 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.0437499 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0375001 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0187497 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0562501 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0687498 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.025 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.13125 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.0812498 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.10625 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.0499998 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.125 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0875002 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0624998 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0625002 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.1125 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0812499 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0812502 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0562497 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.106592 ns, 0.11697 ns);
